def rec(i: int = 0, body: str | None = None) -> LogRecord:
    return LogRecord(body if body is not None else f"record {i}")


class Drops:
    def __init__(self) -> None:
        self.calls: list[tuple[list[str], str]] = []
        self.errors: list[tuple[Exception, int]] = []

    def on_drop(self, records: Sequence[LogRecord], reason: str) -> None:
        self.calls.append(([r.body for r in records], reason))

    def on_error(self, error: Exception, records: Sequence[LogRecord]) -> None:
        self.errors.append((error, len(records)))

    def options(self, **kwargs: object) -> BatchOptions:
        return BatchOptions(on_drop=self.on_drop, on_error=self.on_error, **kwargs)  # type: ignore[arg-type]


class GateExporter:
    """Blocks every export until ``gate`` is set."""

    def __init__(self) -> None:
        self.gate = threading.Event()
        self.entered = threading.Event()
        self.records: list[LogRecord] = []
        self.shutdowns = 0

    def export(self, records: Sequence[LogRecord], *, gzip: bool, timeout_s: float) -> ExportResult:
        self.entered.set()
        self.gate.wait(10)
        self.records.extend(records)
        return ExportResult(accepted=len(records))

    def shutdown(self) -> None:
        self.shutdowns += 1


