def test_exports_full_batches_and_flushes_rest() -> None:
    exporter = InMemoryLogExporter(retries=1)
    processor = BatchProcessor(exporter, BatchOptions(max_batch_size=10, flush_interval_s=30))
    for i in range(25):
        assert processor.add(rec(i))
    processor.flush(5)
    assert [len(b) for b in exporter.batches] == [10, 10, 5]
    assert [r.body for r in exporter.records] == [f"record {i}" for i in range(25)]
    assert exporter.gzip_flags == [True, True, True]
    stats = processor.stats()
    assert stats == BatchStats(queued=0, sent=25, dropped=0, failed=0, retries=3)
    processor.shutdown()
    assert exporter.shutdown_calls == 1


def test_flush_interval_exports_without_flush() -> None:
    exporter = InMemoryLogExporter()
    processor = BatchProcessor(exporter, BatchOptions(flush_interval_s=0.05))
    processor.add(rec(1))
    deadline = time.monotonic() + 5
    while not exporter.records and time.monotonic() < deadline:
        time.sleep(0.01)
    assert len(exporter.records) == 1
    processor.add(rec(2))
    processor.flush(5)
    assert len(exporter.records) == 2
    processor.shutdown()


