def test_drop_newest_when_full() -> None:
    drops = Drops()
    exporter = GateExporter()
    processor = BatchProcessor(
        exporter, drops.options(max_queue_size=2, max_batch_size=1, flush_interval_s=30)
    )
    assert processor.add(rec(0))
    assert exporter.entered.wait(5)  # record 0 is in flight
