def test_block_policy_waits_for_space() -> None:
    exporter = GateExporter()
    processor = BatchProcessor(
        exporter,
        BatchOptions(max_queue_size=1, max_batch_size=1, flush_interval_s=30, drop_policy="block"),
    )
    processor.add(rec(0))
    assert exporter.entered.wait(5)
    processor.add(rec(1))  # fills the queue
    done = threading.Event()
    results: list[bool] = []

    def producer() -> None:
        results.append(processor.add(rec(2)))
        done.set()

    thread = threading.Thread(target=producer)
    thread.start()
    assert not done.wait(0.2)  # blocked
    exporter.gate.set()
    assert done.wait(5)
    thread.join()
    assert results == [True]
    processor.shutdown(5)
    assert len(exporter.records) == 3
    assert processor.stats().dropped == 0


def test_block_policy_drops_when_shut_down_while_waiting() -> None:
    drops = Drops()
    exporter = GateExporter()
    processor = BatchProcessor(
        exporter,
        drops.options(max_queue_size=1, max_batch_size=1, flush_interval_s=30, drop_policy="block"),
    )
    processor.add(rec(0))
    assert exporter.entered.wait(5)
    processor.add(rec(1))
    results: list[bool] = []
    thread = threading.Thread(target=lambda: results.append(processor.add(rec(2))))
    thread.start()
    time.sleep(0.1)
    shutdown = threading.Thread(target=processor.shutdown, args=(0.2,))
    shutdown.start()
    thread.join(5)
    assert results == [False]
    exporter.gate.set()
    shutdown.join(5)
    reasons = [reason for _, reason in drops.calls]
    assert "shutdown" in reasons


