def test_atexit_hook_shuts_down() -> None:
    exporter = InMemoryLogExporter()
    processor = BatchProcessor(exporter, BatchOptions(flush_interval_s=30))
    processor.add(rec(0))
    batch_module._atexit_shutdown(weakref.ref(processor))
    assert len(exporter.records) == 1
    assert exporter.shutdown_calls == 1

    class Dead:
        pass

    gone = Dead()
    ref = weakref.ref(gone)
    del gone
    batch_module._atexit_shutdown(ref)  # type: ignore[arg-type]


