def test_retryable_errors_are_retried() -> None:
    exporter = InMemoryLogExporter()
    exporter.fail_next(2)
    processor = BatchProcessor(
        exporter, BatchOptions(flush_interval_s=30, retry_backoff_s=timedelta(milliseconds=1))
    )
    processor.add(rec(0))
    processor.flush(5)
    stats = processor.stats()
    assert (stats.sent, stats.failed, stats.retries) == (1, 0, 2)
    exporter.fail_next(3)
    processor.add(rec(1))
    processor.flush(5)
    stats = processor.stats()
    assert (stats.sent, stats.failed, stats.retries) == (1, 1, 4)
    processor.shutdown()


def test_non_retryable_and_partial_results_are_final() -> None:
    errors: list[Exception] = []
    calls: list[int] = []

    class Exporter:
        def __init__(self, results: list[ExportResult | Exception]) -> None:
            self.results = results

        def export(
            self, records: Sequence[LogRecord], *, gzip: bool, timeout_s: float
        ) -> ExportResult:
            calls.append(len(records))
            item = self.results.pop(0)
            if isinstance(item, Exception):
                raise item
            return item

        def shutdown(self) -> None:
            pass

    options = BatchOptions(
        flush_interval_s=30, retry_backoff_s=0.001, on_error=lambda e, r: errors.append(e)
    )
    final = BatchProcessor(Exporter([ValidationError("bad request")]), options)
    final.add(rec(0))
    final.flush(5)
    assert calls == [1]
    assert final.stats().failed == 1
    final.shutdown()

    calls.clear()
    returned = BatchProcessor(
        Exporter(
            [
                ExportResult(accepted=0, rejected=1, error=UnavailableError("busy")),
                ExportResult(accepted=1),
            ]
        ),
        options,
    )
    returned.add(rec(0))
    returned.flush(5)
    assert calls == [1, 1]
    assert returned.stats().sent == 1
    returned.shutdown()

    calls.clear()
    partial = BatchProcessor(
        Exporter([ExportResult(accepted=1, rejected=1, error=UnavailableError("half"))]),
        options,
    )
    partial.add(rec(0))
    partial.add(rec(1))
    partial.flush(5)
    assert calls == [2]
    assert (partial.stats().sent, partial.stats().failed) == (1, 1)
    partial.shutdown()
